def transpose(text):
    rows = text.split('\n')
    width = max((len(row) for row in rows), default=0)
    out = []
    for c in range(width):
        last = max(i for i, row in enumerate(rows) if c < len(row))
        out.append(''.join(row[c] if c < len(row) else ' ' for row in rows[:last + 1]))
    return '\n'.join(out)
